import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { MAX_DISTANCE, MAX_SCORE, scoreFor, totalDistance } from './scoring.ts'

interface Fixture {
  order: number[]
  standings: number[]
  score: number
}

// Generated by the Rust test programs/prediction_league/tests/test_score_fixtures.rs.
const fixtures: Fixture[] = JSON.parse(
  readFileSync(
    new URL('../../../programs/prediction_league/tests/fixtures/score_fixtures.json', import.meta.url),
    'utf-8',
  ),
)

describe('scoreFor matches the Rust implementation', () => {
  it('has a meaningful number of fixtures', () => {
    expect(fixtures.length).toBeGreaterThan(300)
  })

  it('agrees on every fixture', () => {
    const mismatches = fixtures.filter((f) => scoreFor(f.order, f.standings) !== f.score)
    expect(mismatches).toEqual([])
  })
})

describe('scoring rule', () => {
  const identity = [0, 1, 2, 3, 4, 5]

  it('perfect prediction is 100', () => {
    expect(scoreFor([2, 0, 1, 5, 4, 3], [2, 0, 1, 5, 4, 3])).toBe(100)
  })

  it('fully reversed order is 0 and has the maximum distance', () => {
    expect(totalDistance([5, 4, 3, 2, 1, 0], identity)).toBe(MAX_DISTANCE)
    expect(scoreFor([5, 4, 3, 2, 1, 0], identity)).toBe(0)
  })

  it('swapping two neighbours scores 89', () => {
    expect(scoreFor([1, 0, 2, 3, 4, 5], identity)).toBe(89)
  })

  it('only the ten documented scores exist, and exactly one order is perfect', () => {
    const perms: number[][] = []
    const permute = (items: number[], start: number) => {
      if (start === items.length) return void perms.push([...items])
      for (let i = start; i < items.length; i++) {
        ;[items[start], items[i]] = [items[i], items[start]]
        permute(items, start + 1)
        ;[items[start], items[i]] = [items[i], items[start]]
      }
    }
    permute([0, 1, 2, 3, 4, 5], 0)
    expect(perms).toHaveLength(720)

    const scores = perms.map((order) => scoreFor(order, identity))
    expect(scores.filter((s) => s === MAX_SCORE)).toHaveLength(1)
    expect(scores.filter((s) => s === 0)).toHaveLength(36)
    expect([...new Set(scores)].sort((a, b) => a - b)).toEqual([0, 11, 22, 33, 44, 56, 67, 78, 89, 100])
  })
})
